<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Reporte <?= htmlspecialchars($reporteActivo['label']) ?></title><style>
.price{text-align:right;color:#047857;font-weight:bold}
@page{size:landscape;margin:12mm}*{box-sizing:border-box}body{margin:0;color:#172033;font-family:Arial,sans-serif;font-size:9px}.toolbar{position:fixed;right:16px;top:16px}.toolbar button{padding:10px 16px;border:0;border-radius:8px;background:#2563eb;color:white;font-weight:bold;cursor:pointer}.report-head{display:flex;justify-content:space-between;align-items:flex-start;padding-bottom:12px;border-bottom:3px solid #2563eb}.report-head h1{margin:0 0 5px;font-size:20px}.report-head p{margin:0;color:#64748b}.meta{text-align:right;line-height:1.5}.filters{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0}.filter{padding:5px 8px;border-radius:6px;background:#eff6ff;color:#1d4ed8}.summary{display:flex;gap:10px;margin-bottom:12px}.summary div{padding:8px 12px;border:1px solid #dbe3ef;border-radius:7px}.summary strong{display:block;margin-top:3px;font-size:14px}table{width:100%;border-collapse:collapse}th{padding:7px;background:#1e3a5f;color:#fff;text-align:left;font-size:7px;text-transform:uppercase}td{padding:6px;border-bottom:1px solid #dbe3ef;vertical-align:top}tr:nth-child(even){background:#f8fafc}.money,.number{text-align:right}.money{color:#047857;font-weight:bold}.code{color:#1d4ed8;font-weight:bold}.error{padding:12px;background:#fef2f2;color:#b91c1c}.signature{display:flex;justify-content:space-around;margin-top:35px}.signature div{width:220px;padding-top:6px;border-top:1px solid #334155;text-align:center}@media print{.toolbar{display:none}}
</style></head><body><div class="toolbar"><button onclick="window.print()">Imprimir / Guardar PDF</button></div><header class="report-head"><div><h1>Reporte de <?= htmlspecialchars($reporteActivo['label']) ?></h1><p>Autoridad Portuaria de Manta · Sistema integral de inventario</p></div><div class="meta"><strong>Generado:</strong> <?= date('d/m/Y H:i') ?><br><strong>Registros:</strong> <?= number_format(count($datosReporte)) ?></div></header><div class="filters"><?php foreach($filtros as $nombre=>$valor): if($valor==='')continue; ?><span class="filter"><strong><?= htmlspecialchars(ucwords(str_replace('_',' ',$nombre))) ?>:</strong> <?= htmlspecialchars($valor) ?></span><?php endforeach; ?></div><?php if($errorReporte): ?><div class="error"><?= htmlspecialchars($errorReporte) ?></div><?php endif; ?><div class="summary"><div>Total de registros<strong><?= number_format(count($datosReporte)) ?></strong></div><div>Tipo de reporte<strong><?= htmlspecialchars($reporteActivo['label']) ?></strong></div></div><table><thead><tr><?php foreach($columnas as $columna): ?><th><?= htmlspecialchars($columna['label']) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($datosReporte as $fila): ?><tr><?php foreach($columnas as $clave=>$columna): $tipo=$columna['type']??'';$valor=$fila[$clave]??''; ?><td class="<?= htmlspecialchars($tipo) ?>"><?php if($tipo==='price'): ?><?= htmlspecialchars(CommonHelper::formatearPrecio($valor)) ?><?php elseif($tipo==='money'): ?><?= htmlspecialchars(CommonHelper::formatearImporte($valor)) ?><?php elseif($tipo==='number'): ?><?= number_format((float)$valor,2) ?><?php elseif($tipo==='date'&&$valor): ?><?= htmlspecialchars(date('d/m/Y H:i',strtotime((string)$valor))) ?><?php else: ?><?= htmlspecialchars((string)$valor) ?><?php endif; ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table><div class="signature"><div>Elaborado por</div><div>Revisado por</div><div>Aprobado por</div></div></body></html>
